// The workspace's server render, built by the frontend (apps/frontend: vite build --ssr src/entry-server.tsx) before
// this Worker is bundled; see docs/server-rendering.md. Its types are restated here so this Worker type-checks before
// that build exists.
// @ts-ignore The module is generated by the frontend's server build.
import * as built from "../../../apps/frontend/dist-ssr/entry-server.js";

export type SessionState = { user: { email: string } | null; unavailable?: boolean };
export type ServerApi = { read: (path: string) => Promise<unknown>; session: () => Promise<SessionState> };
export type Rendered =
  | { kind: "page"; status: number; html: string; queryState: string }
  | { kind: "response"; response: Response }
  | { kind: "signed-out" };

export const render = (built as { render: (request: Request, api: ServerApi, nonce?: string) => Promise<Rendered> }).render;
